import { useState } from 'react';
import { Calendar, ButtonGroup, Button, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(() => startOfDay(new Date()));

  const handleSelect = (date: Date) => {
    const normalized = startOfDay(date);
    setSelectedDate(normalized);
    onChange?.(normalized);
  };

  const quickOptions = [
    { label: 'Сегодня', getValue: () => startOfDay(new Date()) },
    { label: 'Вчера', getValue: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getValue: () => addDays(startOfDay(new Date()), -7) },
  ];

  return (
    <Stack direction="column" gap="var(--jx-space-md)" className="jx-report-date-picker">
      <ButtonGroup>
        {quickOptions.map((option) => (
          <Button
            key={option.label}
            variant="secondary"
            onClick={() => handleSelect(option.getValue())}
          >
            {option.label}
          </Button>
        ))}
      </ButtonGroup>
      <Calendar
        mode="single"
        selected={selectedDate}
        onSelect={(date) => date && handleSelect(date)}
      />
    </Stack>
  );
}

